import type { VariantQaResult } from './contracts';

export interface PreviewQaOptions {
  source?: string;
}

export interface PreviewQaInput {
  html: string;
  options?: PreviewQaOptions;
}

export const runPreviewQa = async (
  input: PreviewQaInput,
): Promise<VariantQaResult> => {
  const source = input.options?.source;
  if (typeof input.html !== 'string' || input.html.trim().length === 0) {
    return {
      status: 'failed',
      issues: [
        {
          kind: 'preview_unavailable',
          detail: source ?? 'inline',
          message: 'Preview HTML was empty',
        },
      ],
      summary: 'Preview unavailable: generated HTML was empty.',
      checkedSource: source,
    };
  }

  return {
    status: 'passed',
    issues: [],
    summary: 'Preview integrity passed.',
    checkedSource: source,
  };
};
